			if c.Verdict != Fail {
				t.Errorf("verdict = %v, want Fail: the direct dial did fail", c.Verdict)
			}
			if c.Reason != ReasonDirectFailedProxyConfigured {
				t.Errorf("reason = %q, want %q", c.Reason, ReasonDirectFailedProxyConfigured)
			}
			if got := factValue(c, "Proxy"); got != tc.want {
				t.Errorf("Proxy fact = %q, want %q", got, tc.want)
			}
			if got := factValue(c, "Address"); got != tg.Addr() {
				t.Errorf("Address fact = %q, want %q: the row still describes the dial", got, tg.Addr())
			}
			if got := factValue(c, "Error"); got != "connection refused" {
				t.Errorf("Error fact = %q, want the dial error kept", got)
			}

			// The gate is unchanged: the failed direct dial still blocks what follows.
			for _, id := range []CheckID{CheckTLSHandshake, CheckHTTP} {
				if b := checkNamed(t, checks, id); b.Verdict != NotApplicable || b.Because != CheckTCP {
					t.Errorf("%s = %v because %q, want N/A because %q", id, b.Verdict, b.Because, CheckTCP)
				}
			}
		})
	}
}

// A dial that succeeds says what it always said: the proxy does not enter it.
func REDACTED(t *testing.T) {
	c := tcpRow(t, fakeEnv{dial: acceptedDial, proxy: proxiedBoth}, target())

	if c.Verdict != OK {
		t.Errorf("verdict = %v, want OK", c.Verdict)
	}
	if want := "Port 443 accepted the connection in 8 ms"; c.Summary != want {
		t.Errorf("summary = %q, want %q", c.Summary, want)
	}
	if c.Reason != "" {
		t.Errorf("reason = %q, want none on a REDACTEDing row", c.Reason)
	}
	if got := factValue(c, "Proxy"); got != "" {
		t.Errorf("Proxy fact = %q, want none: the dial worked", got)
	}
}

// Without a proxy that applies, a refusal is what it was before: the conclusion
// only changes when a proxy is configured for this target.
func TestAFailedDirectDialWithoutAProxyIsUnchanged(t *testing.T) {
	for _, tc := range []struct {
		name  string
		proxy func(*url.URL) netproxy.Decision
	}{
		{"no variable", nil},
		{"no variable, explicitly", perScheme(none(), none())},
		{"NO_PROXY names the target", perScheme(
			decided(netproxy.DecisionExcluded, "HTTPS_PROXY", ""),
			decided(netproxy.DecisionExcluded, "HTTP_PROXY", ""))},
		{"a loopback target", perScheme(
			decided(netproxy.DecisionLoopback, "HTTPS_PROXY", ""),
			decided(netproxy.DecisionLoopback, "HTTP_PROXY", ""))},
		{"an invalid variable", perScheme(decided(netproxy.DecisionInvalid, "HTTPS_PROXY", ""), none())},
		{"both variables invalid", perScheme(
			decided(netproxy.DecisionInvalid, "HTTPS_PROXY", ""),
			decided(netproxy.DecisionInvalid, "HTTP_PROXY", ""))},
	} {
		t.Run(tc.name, func(t *testing.T) {
			c := tcpRow(t, fakeEnv{dial: refusedDial, proxy: tc.proxy}, target())

			if c.Verdict != Fail {
				t.Errorf("verdict = %v, want Fail", c.Verdict)
			}
			if want := "Port 443 does not accept connections"; c.Summary != want {
				t.Errorf("summary = %q, want %q", c.Summary, want)
			}
			if c.Reason != "" {
				t.Errorf("reason = %q, want none: no proxy applies", c.Reason)
			}
			if got := factValue(c, "Proxy"); got != "" {
				t.Errorf("Proxy fact = %q, want none: no proxy applies", got)
			}
			if got := factValue(c, "Error"); got != "connection refused" {
				t.Errorf("Error fact = %q, want the dial error", got)
			}
		})
	}
}

// The help for the new conclusion says the direct path failed and that a proxy
// is configured, and offers something to do that is not the generic advice
// about a service that is down.
func TestTheDirectFailureWithAProxyIsExplained(t *testing.T) {
	c := tcpRow(t, fakeEnv{dial: refusedDial, proxy: proxiedBoth}, target())
	e := Explain(c)

	wantMeans := "The direct path to this port is closed, and that is all this run tests. A proxy is " +
		"configured for this target: behind a mandatory proxy a closed direct path is expected, " +
		"and it says nothing about whether the target is up."
	if e.Means != wantMeans {
		t.Errorf("means = %q, want %q", e.Means, wantMeans)
	}
	for _, word := range []string{"direct path", "proxy"} {
		if !strings.Contains(e.Means, word) {
			t.Errorf("means %q does not say %q", e.Means, word)
		}
	}

	wantDo := "If this target is meant to be reached through the proxy, check it from a client that " +
		"uses it, such as an HTTPS monitor in the Status view. If it is meant to be reached " +
		"directly, add it to NO_PROXY and look for what drops the connection."
	if e.Do != wantDo {
		t.Errorf("do = %q, want %q", e.Do, wantDo)
	}

	generic := Explain(tcpRow(t, fakeEnv{dial: refusedDial}, target()))
	if strings.TrimSpace(e.Do) == "" || e.Do == generic.Do {
		t.Errorf("do = %q: it must be non-empty and differ from the generic TCP Fail advice", e.Do)
	}
	if e.Means == generic.Means {
		t.Error("the explanation is the generic TCP Fail one: it does not mention the proxy")
	}
	if e.Observed != c.Summary {
		t.Errorf("observed = %q, want the summary %q", e.Observed, c.Summary)
	}
}

// The guidance row is a row of the table, not a branch in code: it is reached
// by a battery scenario (TestNoGuidanceRowIsUnreachable fails otherwise), says
// something about the failed state, and leaves the generic row for the other
// failures.
func TestTheDirectFailureGuidanceRowIsInTheTableAndReachable(t *testing.T) {
	var rows int
	for _, g := range explanations {
		if g.check == CheckTCP && g.verdict == Fail && g.reason == ReasonDirectFailedProxyConfigured {
			rows++
			if strings.TrimSpace(g.do) == "" {
				t.Error("the guidance row has nothing to do about the failure")
			}
		}
	}
	if rows != 1 {
		t.Fatalf("explanations has %d rows for tcp/fail/%s, want 1", rows, ReasonDirectFailedProxyConfigured)
	}

	var reached bool
	for _, c := range produced(t) {
		if c.ID == CheckTCP && c.Verdict == Fail && c.Reason == ReasonDirectFailedProxyConfigured {
			reached = true
		}
	}
	if !reached {
		t.Error("no scenario of the battery produces the TCP direct-failed-proxy-configured row")
	}

	// The generic row still serves the failures with no proxy.
	generic := Explain(Check{ID: CheckTCP, Verdict: Fail, Summary: "x"})
	if strings.Contains(generic.Means, "proxy") {
		t.Errorf("the generic TCP Fail explanation mentions a proxy: %q", generic.Means)
	}
}

// The proxy is shown redacted by netproxy, and the TCP row must not put a
// credential back: no summary, fact or explanation carries "@" or a secret.
func TestTheDirectFailureRowCarriesNoCredential(t *testing.T) {
	// What netproxy hands over for REDACTED is scheme://host:port.
	redacted := perScheme(
		decided(netproxy.DecisionProxied, "HTTPS_PROXY", "http://proxy.corp:3128"),
		decided(netproxy.DecisionProxied, "HTTP_PROXY", "http://proxy.corp:3128"))

	c := tcpRow(t, fakeEnv{dial: refusedDial, proxy: redacted}, target())
	if c.Reason != ReasonDirectFailedProxyConfigured {
		t.Fatalf("premise: reason = %q, want %q", c.Reason, ReasonDirectFailedProxyConfigured)
	}
	e := Explain(c)

	texts := []string{c.Summary, e.Observed, e.Means, e.Do}
	for _, f := range c.Facts {
		texts = append(texts, f.Key, f.Value)
	}
	for _, s := range texts {
		for _, bad := range []string{"@", secretUser, secretPass} {
			if strings.Contains(s, bad) {
				t.Errorf("%q contains %q", s, bad)
			}
		}
	}
}

// An invalid variable for one scheme and a valid proxy for the other: the Proxy
// row merges to Invalid, but a proxy is configured all the same, so a failed
// direct dial still says so. The TCP stage reads the row's field, not its text.
func TestAFailedDirectDialWithOneInvalidAndOneProxiedSchemeNamesTheProxy(t *testing.T) {
	proxy := perScheme(
		decided(netproxy.DecisionInvalid, "HTTPS_PROXY", ""),
		decided(netproxy.DecisionProxied, "HTTP_PROXY", "http://proxy.corp:3128"))
	checks := runWith(t, fakeEnv{dial: refusedDial, proxy: proxy}, target())

	if p := checkNamed(t, checks, CheckProxy); p.Reason != ReasonProxyInvalid {
		t.Fatalf("premise: proxy row reason = %q, want %q", p.Reason, ReasonProxyInvalid)
	}
	c := checkNamed(t, checks, CheckTCP)
	if c.Reason != ReasonDirectFailedProxyConfigured {
		t.Errorf("reason = %q, want %q", c.Reason, ReasonDirectFailedProxyConfigured)
	}
	if want := "Port 443 does not accept direct connections; a proxy is configured for this target"; c.Summary != want {
		t.Errorf("summary = %q, want %q", c.Summary, want)
	}
	if got := factValue(c, "Proxy"); got != "http://proxy.corp:3128" {
		t.Errorf("Proxy fact = %q, want the proxied scheme's proxy", got)
	}
}
package netproxy

import (
	"net"
	"net/netip"
	"net/url"
	"os"
	"regexp"
	"strings"
	"unicode"
	"unicode/utf8"
)

// DecisionKind says what the proxy environment variables mean for one URL.
type DecisionKind int

const (
	// DecisionNone: no variable is set for this URL's scheme. It is the zero
	// value, so an unfilled Decision reads as "no proxy".
	DecisionNone DecisionKind = iota
	// DecisionProxied: a proxy carries this URL.
	DecisionProxied
	// DecisionExcluded: a valid variable is set and NO_PROXY names the target.
	DecisionExcluded
	// DecisionLoopback: a valid variable is set, but Go never proxies
	// localhost or a loopback address.
	DecisionLoopback
	// DecisionInvalid: the variable is set and is not a usable proxy URL.
	DecisionInvalid
)

// Decision is what Describe found out about one URL. It carries no credential:
// Proxy is Display's output and an invalid value is named by its variable only.
type Decision struct {
	Kind DecisionKind
	// Variable is the name of the variable read for the URL's scheme, with the
	// case it was read in (HTTPS_PROXY or https_proxy); empty for None.
	Variable string
	// Proxy is Display(proxy) when Kind is DecisionProxied, empty otherwise.
	Proxy string
}

// Describe reports which proxy, if any, applies to u in the process
// environment. The answer comes from FromEnvironment, the function every
// DevDesk client uses; only the variable's name and validity are read here.
func Describe(u *url.URL) Decision {
	return describe(u, os.Getenv, FromEnvironment)
}

// describe is Describe with its inputs injected. sel is not consulted when the
// variables alone settle the answer (None, Invalid), so it may be nil then.
func describe(u *url.URL, getenv func(string) string, sel Selector) Decision {
	var names [2]string
	switch strings.ToLower(u.Scheme) {
	case "https":
		names = [2]string{"HTTPS_PROXY", "https_proxy"}
	case "http":
		names = [2]string{"HTTP_PROXY", "http_proxy"}
	default:
		return Decision{}
	}
	// The first non-empty name wins, like Go's getEnvAny.
	name, value := "", ""
	for _, n := range names {
		if v := getenv(n); v != "" {
			name, value = n, v
			break
		}
	}
	if name == "" {
		return Decision{}
	}
	if !usableProxyValue(value) {
		return Decision{Kind: DecisionInvalid, Variable: name}
	}
	proxy, err := sel(u)
	if err != nil {
		// The error text can quote the proxy URL, credentials included.
		return Decision{Kind: DecisionInvalid, Variable: name}
	}
	if proxy != nil {
		return Decision{Kind: DecisionProxied, Variable: name, Proxy: Display(proxy)}
	}
	// A nil proxy with a valid variable: Go skips a loopback target whatever
	// NO_PROXY says, otherwise NO_PROXY named it.
	if isLoopbackHost(u.Hostname()) {
		return Decision{Kind: DecisionLoopback, Variable: name}
	}
	return Decision{Kind: DecisionExcluded, Variable: name}
}

// explicitScheme matches a value that starts with a URL scheme, as opposed to
// one that only has "://" somewhere in its path or query.
var explicitScheme = regexp.MustCompile(`^[A-Za-z][A-Za-z0-9+.-]*://`)

// usableProxyValue follows Go's parseProxy (url.Parse, then a retry with
// "http://" in front for a value without a scheme) and is stricter on three
// points, because Go ignores an unusable value and FromEnvironment alone
// cannot tell it from "no proxy":
//   - the host must not be empty;
//   - a value holding "@" must end up with userinfo, otherwise the credential
//     was mangled (an unescaped "/", "?" or "#" before the "@") and the text
//     before it became the host;
//   - the host must be printable UTF-8, since it ends up on screen.
func usableProxyValue(value string) bool {
	explicit := explicitScheme.MatchString(value)
	u, err := url.Parse(value)
	switch {
	case err != nil && explicit:
		return false
	case err == nil && u.Scheme != "" && u.Host != "":
		// Parsed as written.
	case err == nil && explicit:
		// An explicit scheme with no host, such as "http://".
		return false
	default:
		u, err = url.Parse("http://" + value)
		if err != nil {
			return false
		}
	}
	if u.Host == "" || (u.User == nil && strings.Contains(value, "@")) {
		return false
	}
	return isPrintable(u.Host)
}

// isPrintable reports whether s is valid UTF-8 made of printable runes only.
func isPrintable(s string) bool {
	if !utf8.ValidString(s) {
		return false
	}
	for _, r := range s {
		if !unicode.IsPrint(r) {
			return false
		}
	}
	return true
}

// isLoopbackHost reports whether host is localhost or a loopback address.
func isLoopbackHost(host string) bool {
	if strings.EqualFold(host, "localhost") {
		return true
	}
	addr, err := netip.ParseAddr(host)
	return err == nil && addr.Unmap().IsLoopback()
}

// defaultPorts are the ports Display shows when the URL names none.
var defaultPorts = map[string]string{
	"http":    "80",
	"https":   "443",
	"socks5":  "1080",
	"socks5h": "1080",
}

// Display renders a proxy URL as scheme://host:port and nothing else: never
// userinfo, path, query, fragment or IPv6 zone. It is the only way a proxy leaves this
// package for the screen. A scheme with no known default port shows no port
// unless the URL names one. Display(nil) is empty.
func Display(proxy *url.URL) string {
	if proxy == nil {
		return ""
	}
	port := proxy.Port()
	if port == "" {
		port = defaultPorts[strings.ToLower(proxy.Scheme)]
	}
	// The zone of a link-local address can be any text: drop it.
	host, _, _ := strings.Cut(proxy.Hostname(), "%")
	if port != "" {
		host = net.JoinHostPort(host, port)
	} else if strings.Contains(host, ":") {
		host = "[" + host + "]"
	}
	return proxy.Scheme + "://" + host
}

// Phase is one named, non-overlapping span within a check's Duration — a
// waterfall row. Phases are sequential and sum to Duration; a check with
// nothing to break down (most of them: one dial, one handshake) leaves this
// nil rather than a single phase covering the whole thing, which would say
// nothing a bar chart couldn't already say better as a number.
type Phase struct {
	Name     string
	Duration time.Duration
}

// Check is one answered question.
type Check struct {
	ID      CheckID
	Stage   StageID
	Title   string
	Verdict Verdict
	// Summary is the one line the results table shows. It states what was
	// observed, never what to do about it — the advice belongs to the
	// explanation layer, which is keyed on ID.
	Summary string
	Facts   []Fact
	// Duration is how long the observation behind this check took, when
	// timed. Zero means untimed — a check that answers instantly (DNS
	// resolution) or one nothing has instrumented yet.
	Duration time.Duration
	// Phases breaks Duration down into a waterfall, when there is more than
	// one span worth showing separately (today: the HTTP check's DNS,
	// connect, TLS, server wait and content transfer). Nil elsewhere.
	Phases []Phase
	// Because is set only when Verdict is NotApplicable *and* the cause was an
	// upstream failure. Empty on a NotApplicable that simply has no meaning
	// here, which is what separates "blocked" from "irrelevant".
	Because CheckID
	// Reason is a stable sub-code for a verdict that has more than one cause.
	//
	// It exists because the remedies differ where the verdict does not: a chain
	// that fails because the leaf is self-signed, because the server sent no
	// intermediates, and because the root is unknown are one Fail with three
	// different things to go and do. Summary already says which in prose;
	// Reason is what an explanation — or a serialization — can switch on.
	//
	// Empty is the common case: most verdicts have exactly one cause.
	Reason Reason
	// Routes is set on CheckRoute only: one lookup per address asked, in the
	// order asked. Nil on a placeholder (skipped or cancelled stage). It holds
	// raw errors and is never shown nor serialized.
	Routes []RouteLookup
	// Proxy is set on CheckProxy only, when at least one scheme is proxied: the
	// redacted proxy as shown, https first. It lets the connect stage tell that a
	// proxy applies without parsing a Summary. It is never shown nor serialized.
	Proxy string
}

// Reason discriminates the causes of a verdict that has several. It is stable:
// the guidance table is keyed on it.
type Reason string

